-- ============================================
-- INFORME_BUSQUEDAS: búsquedas con texto que hacen los usuarios (reportes:
-- términos más buscados y búsquedas sin resultados = lo que falta sistematizar)
-- ============================================
CREATE TABLE IF NOT EXISTS "INFORME_BUSQUEDAS" (
    "ID_BUSQUEDA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_INFORME_BUSQUEDAS" PRIMARY KEY,
    "ID_USUARIO" INT NULL CONSTRAINT "FK_INFORME_BUSQUEDAS_USUARIO" REFERENCES "USUARIOS" ("ID_USUARIO"),
    "TEXTO" VARCHAR(200) NOT NULL,
    "RESULTADOS" INT NOT NULL,
    "FECHA" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS "IX_INFORME_BUSQUEDAS_FECHA" ON "INFORME_BUSQUEDAS" ("FECHA");
CREATE INDEX IF NOT EXISTS "IX_INFORME_BUSQUEDAS_USUARIO" ON "INFORME_BUSQUEDAS" ("ID_USUARIO");
